mapper.update:
update  MST_DEALER_DETAIL_INFO set  DEALER_PARTY_TYPE = #{dealerPartyType} , DEALER_PARTY_NAME = #{dealerPartyName} ,
        DEALER_PARTY_NO = #{dealerPartyNo} ,
        TRADER_NAME = #{trader,jdbcType=VARCHAR} ,TRADER_NO = #{traderNo,jdbcType=VARCHAR},IS_OUR = #{isOur,jdbcType=VARCHAR} where SEQ_NO = #{seqNo,jdbcType=VARCHAR}

update  MST_DEALER_DETAIL_INFO set
         TRADER_NAME = #{trader,jdbcType=VARCHAR} ,TRADER_NO = #{traderNo,jdbcType=VARCHAR},IS_OUR = #{isOur,jdbcType=VARCHAR}
          where SEQ_NO = #{seqNo,jdbcType=VARCHAR}

mapper.select:
select distinct mdi.DEALER_NO dealerNo, mdi.TRADE_MARKET tradeMarket, mci.CUSTOMER_ID customerId, mci.CUSTOMER_NAME dealerName from MST_DEALER_INFO mdi left JOIN MST_DEALER_DETAIL_INFO MDDI on mdi.DEALER_NO = MDDI.DEALER_NO and MDDI.CUSTOMER_ID=mdi.CUSTOMER_ID left join MST_CUSTOMER_INFO mci on mci.CUSTOMER_ID = mdi.CUSTOMER_ID
mdi.TRADE_MARKET = #{tradeMarket}
and SSAI.TRD_ACCT_ID = #{acctNo}
and MDDI.IS_OUR = #{isOur}
and mdi.CUSTOMER_ID = #{dealerNo}
and mci.CUSTOMER_NAME like concat(concat('%',#{dealerName}),'%')
and MDDI.TRADER_NO like concat(concat('%',#{traderNo}),'%')
and MDDI.TRADER_NAME like concat(concat('%',#{traderName}),'%')
and MDDI.DEALER_PARTY_NO like concat(concat('%',#{dealerPartyNo}),'%')
and MDDI.DEALER_PARTY_NAME like concat(concat('%',#{dealerPartyName}),'%')

select count(1) from MST_DEALER_INFO mdi
inner join MST_DEALER_DETAIL_INFO MDDI on mdi.DEALER_NO = MDDI.DEALER_NO AND MDI.CUSTOMER_ID = MDDI.CUSTOMER_ID
WHERE mdi.CUSTOMER_ID = #{customerId} AND MDI.DEALER_NO = #{dealerNo} and mddi.TRADER_NO = #{traderNo}

mapper.delete:
delete from  MST_DEALER_DETAIL_INFO mddi

    mddi.CUSTOMER_ID = #{customerId,jdbcType="VARCHAR"}
    and mddi.DEALER_PARTY_NO =#{dealerPartyNo,jdbcType="VARCHAR"}
    and mddi.TRADER_NO = #{traderNo,jdbcType="VARCHAR"}

delete from MST_DEALER_INFO
where CUSTOMER_ID = #{customerId}
and DEALER_NO = #{dealerNo}
